/**
 * lunR: gateway agent bridge.
 *
 * Owns the sessionKey → AgentSession mapping: an LRU cache (cap 20) over
 * live sessions, backed by store.ts so conversations survive daemon restarts
 * (a stored sessionFile is reopened via SessionManager.open, which
 * createAgentSession restores history from; a missing file starts fresh with
 * a one-line warning).
 *
 * New sessions replicate main.ts's headless wiring: SettingsManager +
 * DefaultResourceLoader with the builtin extension factories + the three
 * lunr bridges, then bindExtensions({ mode: "print" }) like print-mode.
 *
 * Busy guard: one turn per session at a time. Messages arriving mid-turn are
 * queued (cap 5, oldest dropped with a notice) and drained FIFO as a single
 * concatenated follow-up turn once the running turn ends; runTurn returns
 * the QUEUED sentinel for those, and the follow-up turn's result is
 * delivered via callbacks.onFollowUpResult.
 *
 * Streaming: subscribes to session events and converts cumulative
 * message_update snapshots into deltas for callbacks.onDelta.
 *
 * isGatewayTurn()/runDepth: incremented around every prompt() so Phase 4
 * (cron↔gateway delivery) and extensions can detect they run inside a
 * gateway turn and refuse self-scheduling. Every prompt() also runs inside
 * runWithOrigin(source, ...) (core/cron/origin-context) so tools executing
 * during the turn — e.g. the `cron` tool's create action — can read the chat
 * the message came from and stamp it as the job's delivery origin.
 */

import { existsSync } from "node:fs";
import type { AgentMessage, ThinkingLevel } from "@earendil-works/pi-agent-core";
import type { AssistantMessage, ImageContent } from "@earendil-works/pi-ai";
import type { Model } from "@earendil-works/pi-ai/compat";
import type { AgentSession, AgentSessionEvent, SessionStats } from "../core/agent-session.ts";
import type { CompactionResult } from "../core/compaction/index.ts";
import { runWithOrigin } from "../core/cron/origin-context.ts";
import type { ContextUsage, SessionShutdownEvent, ToolDefinition } from "../core/extensions/types.ts";
import type { ModelRuntime } from "../core/model-runtime.ts";
import { createPermissionContext, deletePermissionContext } from "../core/permissions.ts";
import type { ReadonlySessionManager, SessionManager, SessionMessageEntry } from "../core/session-manager.ts";
import { processImage } from "../utils/image-process.ts";
import { getSession, putSession, removeSession, touchSession } from "./store.ts";
import type { InboundAttachment, MessageEvent, SessionSource } from "./types.ts";

function isUserMessageEntry(entry: { type: string }): entry is SessionMessageEntry {
	return entry.type === "message";
}

/** runTurn resolves with this when the message was queued behind a running turn. */
export const QUEUED = "__lunr_gateway_queued__";

const CACHE_CAP = 20;
const QUEUE_CAP = 5;

let runDepth = 0;

/** True while a gateway turn's prompt() is in flight. */
export function isGatewayTurn(): boolean {
	return runDepth > 0;
}

export function gatewayRunDepth(): number {
	return runDepth;
}

export interface TurnCallbacks {
	/** Assistant text delta during streaming (converted from cumulative snapshots). */
	onDelta?: (delta: string) => void;
	/** Final text of a drained-queue follow-up turn (deliver it like a normal reply). */
	onFollowUpResult?: (text: string) => void;
	/** Error from a drained-queue follow-up turn. */
	onError?: (message: string) => void;
}

export interface BridgeSessionStatus {
	busy: boolean;
	queueDepth: number;
	createdAt?: string;
}

/**
 * Structural session shape the bridge needs — satisfied by AgentSession,
 * fakeable in tests. Expanded to support gateway slash commands.
 */
export interface BridgeSession {
	prompt(text: string, options?: { source?: "extension"; images?: ImageContent[] }): Promise<void>;
	abort(): Promise<void> | void;
	subscribe(listener: (event: AgentSessionEvent) => void): () => void;
	readonly state: { messages: AgentMessage[] };
	readonly extensionRunner?: {
		hasHandlers(eventType: string): boolean;
		emit(event: SessionShutdownEvent): Promise<unknown>;
	};
	dispose?(): void;
	readonly isStreaming: boolean;
	readonly isCompacting?: boolean;
	readonly model?: Model<any>;
	readonly modelRuntime: ModelRuntime;
	readonly thinkingLevel: ThinkingLevel;
	readonly messages: AgentMessage[];
	readonly systemPrompt: string;
	readonly sessionManager?: ReadonlySessionManager;

	getActiveToolNames(): string[];
	getToolDefinition(name: string): ToolDefinition | undefined;
	getAvailableThinkingLevels(): ThinkingLevel[];
	supportsThinking(): boolean;
	setThinkingLevel(level: ThinkingLevel): void;
	setModel(model: Model<any>): Promise<void>;
	compact(customInstructions?: string): Promise<CompactionResult>;
	navigateTree(
		targetId: string,
		options?: { summarize?: boolean; customInstructions?: string; replaceInstructions?: boolean; label?: string },
	): Promise<{ editorText?: string; editorImages?: ImageContent[]; cancelled: boolean; aborted?: boolean }>;
	getContextUsage(): ContextUsage | undefined;
	getSessionStats(): SessionStats;
	setSessionName(name: string): void;
}

export type SessionFactory = (key: string, reopen: { sessionFile: string } | undefined) => Promise<BridgeSession>;

export async function shutdownBridgeSession(
	session: BridgeSession,
	reason: SessionShutdownEvent["reason"],
	targetSessionFile?: string,
): Promise<void> {
	try {
		if (session.extensionRunner?.hasHandlers("session_shutdown")) {
			await session.extensionRunner.emit({
				type: "session_shutdown",
				reason,
				...(targetSessionFile ? { targetSessionFile } : {}),
			});
		}
	} catch (error) {
		console.error("[gateway] session shutdown handler failed", error);
	} finally {
		session.dispose?.();
	}
}

interface CacheEntry {
	session: BridgeSession;
	busy: boolean;
	queue: MessageEvent[];
	dropped: number;
	unsubscribe?: () => void;
}

/**
 * Default factory: headless session with the builtin extensions, mirroring
 * main.ts (minus TUI) + print-mode's bindExtensions.
 *
 * The heavy wiring is imported LAZILY: a static import of
 * builtin-extensions/index.ts here would pull the whole extension + TUI
 * graph into every consumer of this module (router tests, `gateway status`)
 * and trip the known ashxj-tui ↔ package-barrel cycle (see AGENTS.md
 * "Barrel-import guard"). Loading it on first session creation keeps module
 * import light and matches how main.ts loads it in the real CLI.
 */
async function defaultSessionFactory(key: string, reopen: { sessionFile: string } | undefined): Promise<AgentSession> {
	const [
		{ loadAllBuiltinExtensions },
		{ getAgentDir },
		{ registerCustomizeBridge },
		{ registerMemoryCapBridge },
		{ registerModelTierBridge },
		{ createAgentSessionFromServices, createAgentSessionServices },
		{ SessionManager },
		{ SettingsManager },
		{ bindRuntimeBridges },
	] = await Promise.all([
		import("../builtin-extensions/index.ts"),
		import("../config.ts"),
		import("../core/customize.ts"),
		import("../core/memory-cap.ts"),
		import("../core/model-tiers.ts"),
		import("../core/agent-session-services.ts"),
		import("../core/session-manager.ts"),
		import("../core/settings-manager.ts"),
		import("../core/runtime-bridges.ts"),
	]);
	const cwd = process.cwd();
	const agentDir = getAgentDir();
	const settingsManager = SettingsManager.create(cwd, agentDir, { projectTrusted: false });
	// Same bridges main.ts registers before extensions load.
	registerModelTierBridge(settingsManager);
	registerMemoryCapBridge(settingsManager);
	registerCustomizeBridge(settingsManager);

	let sessionManager: SessionManager;
	if (reopen && existsSync(reopen.sessionFile)) {
		sessionManager = SessionManager.open(reopen.sessionFile);
	} else {
		if (reopen) {
			console.warn(`[gateway] stored session file missing for ${key}; starting a fresh session`);
		}
		sessionManager = SessionManager.create(cwd);
	}

	// Services-first (mirrors main.ts): extension-registered providers (e.g.
	// ollama-cloud) must land in the shared ModelRuntime BEFORE session
	// creation — otherwise findInitialModel can't resolve the user's default
	// model and silently falls back to an arbitrary catalog provider (this
	// exact bug sent gateway turns to openrouter with no key → 401).
	const services = await createAgentSessionServices({
		cwd,
		agentDir,
		settingsManager,
		resourceLoaderOptions: { extensionFactories: await loadAllBuiltinExtensions() },
	});
	const { session } = await createAgentSessionFromServices({ services, sessionManager });
	bindRuntimeBridges({ session, services });
	await session.bindExtensions({
		mode: "print",
		onError: (err) => console.error(`[gateway] extension error (${err.extensionPath}): ${err.error}`),
	});
	return session;
}

/** Final assistant text, print-mode style; throws on error/aborted stop. */
function extractFinalText(session: BridgeSession): string {
	const messages = session.state.messages;
	const last = messages[messages.length - 1];
	if (last?.role !== "assistant") return "";
	const assistant = last as AssistantMessage;
	if (assistant.stopReason === "error" || assistant.stopReason === "aborted") {
		throw new Error(assistant.errorMessage || `Request ${assistant.stopReason}`);
	}
	let text = "";
	for (const content of assistant.content) {
		if (content.type === "text") text += content.text;
	}
	return text;
}

export class AgentBridge {
	private cap: number;
	private readonly sessionFactory: SessionFactory;
	private readonly cache = new Map<string, CacheEntry>();
	private readonly redoStack = new Map<string, string[]>();
	private readonly creating = new Map<string, Promise<CacheEntry>>();

	constructor(options: { cacheCap?: number; sessionFactory?: SessionFactory } = {}) {
		this.cap = options.cacheCap ?? CACHE_CAP;
		this.sessionFactory = options.sessionFactory ?? defaultSessionFactory;
	}

	/**
	 * Run one conversational turn. Resolves with the final assistant text, or
	 * the QUEUED sentinel when the session was busy (router must not reply).
	 */
	async runTurn(key: string, event: MessageEvent, callbacks: TurnCallbacks = {}): Promise<string> {
		const entry = await this.getOrCreate(key);
		if (entry.busy) {
			if (entry.queue.length >= QUEUE_CAP) {
				entry.queue.shift();
				entry.dropped++;
			}
			entry.queue.push(event);
			return QUEUED;
		}
		entry.busy = true;
		let result: string;
		try {
			result = await this.runPrompt(entry, event.text, callbacks, event.source, event.attachments);
		} catch (err) {
			entry.busy = false;
			throw err;
		}
		touchSession(key);
		// Drain queued messages as one follow-up turn, fire-and-forget. The busy
		// flag stays set until the queue is empty so turn ordering is strict;
		// the follow-up result arrives via callbacks.onFollowUpResult.
		void this.drainQueue(entry, callbacks).finally(() => {
			entry.busy = false;
		});
		return result;
	}

	async abort(key: string): Promise<void> {
		await this.cache.get(key)?.session.abort();
	}

	/** Return the live session for a key, or null when none exists yet. */
	async getSession(key: string): Promise<BridgeSession | null> {
		const cached = this.cache.get(key);
		if (cached) return cached.session;
		if (!getSession(key)) return null;
		return (await this.getOrCreate(key)).session;
	}

	/** Switch the chat to a different persisted session file. */
	async switchSession(key: string, sessionFile: string): Promise<void> {
		const entry = this.cache.get(key);
		if (entry?.busy) {
			throw new Error("Session is busy — /stop first or wait");
		}
		if (entry) {
			const oldSessionId = entry.session.sessionManager?.getSessionId();
			entry.unsubscribe?.();
			this.cache.delete(key);
			await shutdownBridgeSession(entry.session, "resume", sessionFile);
			if (oldSessionId) deletePermissionContext(oldSessionId);
		}
		removeSession(key);
		this.redoStack.delete(key);

		const session = await this.sessionFactory(key, { sessionFile });
		const newFile = session.sessionManager?.getSessionFile();
		const newSessionId = session.sessionManager?.getSessionId();
		if (newFile) {
			putSession(key, { sessionId: newSessionId ?? key, sessionFile: newFile });
		}
		if (newSessionId) {
			createPermissionContext(newSessionId);
		}
		const newEntry: CacheEntry = { session, busy: false, queue: [], dropped: 0 };
		this.cache.set(key, newEntry);
		newEntry.unsubscribe = this._subscribeToSession(key, newEntry);
		await this._enforceCacheCap(key);
	}

	/** Undo the last user turn and push the previous leaf onto the redo stack. */
	async undo(key: string): Promise<{ userText: string }> {
		const session = await this.getSession(key);
		if (!session) throw new Error("No session");
		if (session.isStreaming) throw new Error("Wait for the current response to finish");
		const branch = session.sessionManager?.getBranch() ?? [];
		let lastUserIndex = -1;
		for (let i = branch.length - 1; i >= 0; i--) {
			const entry = branch[i];
			if (isUserMessageEntry(entry) && entry.message.role === "user") {
				lastUserIndex = i;
				break;
			}
		}
		if (lastUserIndex === -1) throw new Error("Nothing to undo");
		const lastUser = branch[lastUserIndex];
		if (!isUserMessageEntry(lastUser)) throw new Error("Nothing to undo");

		const leafId = session.sessionManager?.getLeafId() ?? null;
		let targetId: string;
		if (lastUser.id === leafId) {
			if (!lastUser.parentId) throw new Error("Nothing to undo");
			targetId = lastUser.parentId;
		} else {
			targetId = lastUser.id;
		}

		const result = await session.navigateTree(targetId, {});
		if (result.cancelled) throw new Error("Navigation cancelled");

		if (leafId) {
			const stack = this.redoStack.get(key) ?? [];
			stack.push(leafId);
			this.redoStack.set(key, stack);
		}

		return { userText: extractUserText(lastUser.message) };
	}

	/** Redo to the leaf saved by the most recent undo. */
	async redo(key: string): Promise<void> {
		const session = await this.getSession(key);
		if (!session) throw new Error("No session");
		if (session.isStreaming) throw new Error("Wait for the current response to finish");
		const stack = this.redoStack.get(key) ?? [];
		const targetId = stack.pop();
		if (!targetId) throw new Error("Nothing to redo");
		this.redoStack.set(key, stack);

		const result = await session.navigateTree(targetId, {});
		if (result.cancelled) {
			stack.push(targetId);
			this.redoStack.set(key, stack);
			throw new Error("Navigation cancelled");
		}
	}

	/** Test/debug hook: how many redo targets are saved for a key. */
	getRedoStackLength(key: string): number {
		return this.redoStack.get(key)?.length ?? 0;
	}

	/** Drop the cached session (disposing it) and forget the store entry (/new, /reset). */
	async reset(key: string): Promise<void> {
		const entry = this.cache.get(key);
		if (entry) {
			// lunr: /new while busy must stop the live turn and drop queued follow-ups
			// before dispose, otherwise drainQueue can still fire on the torn-down entry.
			entry.queue.length = 0;
			entry.dropped = 0;
			try {
				await entry.session.abort();
			} catch {
				// best-effort; dispose still tears the session down
			}
			entry.unsubscribe?.();
			this.cache.delete(key);
			await shutdownBridgeSession(entry.session, "new");
		}
		removeSession(key);
		this.redoStack.delete(key);
	}

	getStatus(key: string): BridgeSessionStatus {
		const entry = this.cache.get(key);
		return {
			busy: entry?.busy ?? false,
			queueDepth: entry?.queue.length ?? 0,
			createdAt: getSession(key)?.createdAt,
		};
	}

	/** One prompt → final text. Increments runDepth; streams deltas when asked. */
	private async runPrompt(
		entry: CacheEntry,
		text: string,
		callbacks: TurnCallbacks,
		source: SessionSource,
		attachments?: InboundAttachment[],
	): Promise<string> {
		const { session } = entry;
		let unsubscribe: (() => void) | undefined;
		if (callbacks.onDelta) {
			const onDelta = callbacks.onDelta;
			let streamedLen = 0;
			unsubscribe = session.subscribe((event: AgentSessionEvent) => {
				if (event.type !== "message_update") return;
				const assistantEvent = event.assistantMessageEvent;
				if (assistantEvent.type !== "text_delta") return;
				let full = "";
				for (const content of assistantEvent.partial.content) {
					if (content.type === "text") full += content.text;
				}
				if (full.length < streamedLen) streamedLen = 0; // new assistant message (tool-call boundary)
				if (full.length > streamedLen) {
					onDelta(full.slice(streamedLen));
					streamedLen = full.length;
				}
			});
		}
		runDepth++;
		try {
			// lunr: convert inbound image attachments to ImageContent for the model.
			// processImage normalizes + resizes under the inline 4.5MB base64 limit;
			// failures become bracketed text notes so the model explains the gap.
			const images: ImageContent[] = [];
			const notes: string[] = [];
			for (const attachment of attachments ?? []) {
				const bytes = Buffer.from(attachment.data, "base64");
				const processed = await processImage(new Uint8Array(bytes), attachment.mimeType);
				if (processed.ok) {
					images.push({ type: "image", data: processed.data, mimeType: processed.mimeType });
					for (const hint of processed.hints) notes.push(hint);
				} else {
					notes.push(processed.message);
				}
			}
			const promptText = notes.length > 0 ? `${text}\n\n${notes.join(" ")}` : text;
			// AsyncLocalStorage origin: tools executing during this turn (e.g. the
			// `cron` tool) can read the chat the message came from. Propagates
			// through the awaited prompt() call tree.
			await runWithOrigin(
				{
					platform: source.platform,
					chatId: source.chatId,
					threadId: source.threadId,
					chatType: source.chatType,
				},
				() => session.prompt(promptText, { source: "extension", ...(images.length ? { images } : {}) }),
			);
		} finally {
			runDepth--;
			unsubscribe?.();
		}
		return extractFinalText(session);
	}

	/** Drain the queue FIFO: all queued messages become one concatenated turn. */
	private async drainQueue(entry: CacheEntry, callbacks: TurnCallbacks): Promise<void> {
		while (entry.queue.length > 0) {
			const items = entry.queue.splice(0);
			const parts = items.map((item) => item.text);
			const attachments = items.flatMap((item) => item.attachments ?? []);
			if (entry.dropped > 0) {
				parts.unshift(`[gateway: ${entry.dropped} earlier message(s) were dropped — the queue was full]`);
				entry.dropped = 0;
			}
			try {
				// Follow-up turns are final-only: no streaming callbacks. The origin
				// is the chat of the latest queued message.
				const text = await this.runPrompt(
					entry,
					parts.join("\n\n"),
					{},
					items[items.length - 1].source,
					attachments,
				);
				callbacks.onFollowUpResult?.(text);
			} catch (err) {
				callbacks.onError?.(err instanceof Error ? err.message : String(err));
				return;
			}
		}
	}

	private async getOrCreate(key: string): Promise<CacheEntry> {
		const cached = this.cache.get(key);
		if (cached) {
			// LRU refresh
			this.cache.delete(key);
			this.cache.set(key, cached);
			return cached;
		}
		// Coalesce concurrent creation for the same key.
		let pending = this.creating.get(key);
		if (!pending) {
			pending = this.createEntry(key);
			this.creating.set(key, pending);
			try {
				await pending;
			} finally {
				this.creating.delete(key);
			}
		}
		return pending;
	}

	private async createEntry(key: string): Promise<CacheEntry> {
		const stored = getSession(key);
		const session = await this.sessionFactory(key, stored ? { sessionFile: stored.sessionFile } : undefined);
		const sessionFile = session.sessionManager?.getSessionFile();
		const sessionId = session.sessionManager?.getSessionId();
		if (sessionFile) {
			putSession(key, { sessionId: sessionId ?? key, sessionFile });
		}
		if (sessionId) {
			createPermissionContext(sessionId);
		}
		const entry: CacheEntry = { session, busy: false, queue: [], dropped: 0, unsubscribe: undefined };
		this.cache.set(key, entry);
		entry.unsubscribe = this._subscribeToSession(key, entry);
		await this._enforceCacheCap(key);
		return entry;
	}

	private async _enforceCacheCap(protectedKey?: string): Promise<void> {
		while (this.cache.size > this.cap) {
			let oldestKey: string | undefined;
			let oldest: CacheEntry | undefined;
			for (const [key, entry] of this.cache) {
				if (key === protectedKey) continue;
				if (entry.busy) continue;
				oldestKey = key;
				oldest = entry;
				break;
			}
			if (!oldest || !oldestKey) {
				// Every cached session is busy (or is the protected new entry);
				// grow the cap temporarily rather than killing an in-flight turn.
				this.cap = this.cache.size;
				break;
			}
			oldest.unsubscribe?.();
			this.cache.delete(oldestKey);
			await shutdownBridgeSession(oldest.session, "quit");
			const evictedSessionId = oldest.session.sessionManager?.getSessionId();
			if (evictedSessionId) deletePermissionContext(evictedSessionId);
		}
	}

	private _subscribeToSession(key: string, entry: CacheEntry): () => void {
		return entry.session.subscribe((event) => this._handleSessionEvent(key, event));
	}

	private _handleSessionEvent(key: string, event: AgentSessionEvent): void {
		if (event.type === "message_start" && event.message?.role === "user") {
			this.redoStack.delete(key);
		}
	}
}

function extractUserText(message: AgentMessage): string {
	let text = "";
	if ("content" in message && Array.isArray(message.content)) {
		for (const block of message.content) {
			if (
				block &&
				typeof block === "object" &&
				"type" in block &&
				block.type === "text" &&
				"text" in block &&
				typeof block.text === "string"
			) {
				text += block.text;
			}
		}
	}
	return text;
}

text:
/**
 * Install-time feature catalog. Persistence is ~/.lunr/agent/install-features.json
 * (getAgentDir()). Secrets never land here — they go to gateway.json.
 */

import { chmodSync, existsSync, mkdirSync, readFileSync, renameSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { appendDebugLog, getAgentDir, VERSION } from "../config.ts";
import { loadGatewayConfig, saveGatewayConfig } from "../gateway/config.ts";

export type FeatureId = "chat-platforms";

export interface FeatureOptionSpec {
	id: string;
	type: "boolean" | "secret";
	prompt: string;
	default?: boolean;
	askWhen?: FeatureId;
}

export interface FeatureSpec {
	id: FeatureId;
	title: string;
	summary: string;
	defaultEnabled: boolean;
	options: FeatureOptionSpec[];
}

export const FEATURE_CATALOG: FeatureSpec[] = [
	{
		id: "chat-platforms",
		title: "Chat platforms",
		summary: "Discord + Telegram gateway so lunR can talk in chat apps.",
		defaultEnabled: false,
		options: [
			{
				id: "autostart",
				type: "boolean",
				prompt: "Auto-start the lunR gateway daemon when you log in?",
				default: false,
				askWhen: "chat-platforms",
			},
			{
				id: "telegram-token",
				type: "secret",
				prompt: "Telegram bot token (empty skips; stored in gateway.json)",
				askWhen: "chat-platforms",
			},
			{
				id: "discord-token",
				type: "secret",
				prompt: "Discord bot token (empty skips; stored in gateway.json)",
				askWhen: "chat-platforms",
			},
		],
	},
];

export interface InstalledFeatureState {
	enabled: boolean;
	options: Record<string, boolean | string | number>;
}

export interface InstallFeaturesFile {
	schemaVersion: 1;
	installerVersion: string;
	installMethod: "binary";
	installedAt: string;
	updatedAt: string;
	inferUntil?: string;
	features: Record<string, InstalledFeatureState>;
}

export const CHAT_PLATFORMS_INFER_UNTIL = "0.2.0";

export function installFeaturesPath(): string {
	return join(getAgentDir(), "install-features.json");
}

export function getFeatureSpec(id: string): FeatureSpec | undefined {
	return FEATURE_CATALOG.find((f) => f.id === id);
}

export function getFeatureOptionSpec(id: string, option: string): FeatureOptionSpec | undefined {
	return getFeatureSpec(id)?.options.find((o) => o.id === option);
}

/** Compare x.y.z; missing parts count as 0. */
export function versionGte(a: string, b: string): boolean {
	const pa = a.split(".").map((p) => Number.parseInt(p, 10) || 0);
	const pb = b.split(".").map((p) => Number.parseInt(p, 10) || 0);
	for (let i = 0; i < 3; i++) {
		const d = (pa[i] ?? 0) - (pb[i] ?? 0);
		if (d !== 0) return d > 0;
	}
	return true;
}

function emptyFile(now = new Date().toISOString()): InstallFeaturesFile {
	return {
		schemaVersion: 1,
		installerVersion: VERSION,
		installMethod: "binary",
		installedAt: now,
		updatedAt: now,
		features: {},
	};
}

function sanitizeState(raw: unknown): InstalledFeatureState | undefined {
	if (raw == null || typeof raw !== "object" || Array.isArray(raw)) return undefined;
	const r = raw as Record<string, unknown>;
	if (typeof r.enabled !== "boolean") return undefined;
	const options: Record<string, boolean | string | number> = {};
	if (r.options != null && typeof r.options === "object" && !Array.isArray(r.options)) {
		for (const [k, v] of Object.entries(r.options as Record<string, unknown>)) {
			if (typeof v === "boolean" || typeof v === "string" || typeof v === "number") {
				options[k] = v;
			}
		}
	}
	return { enabled: r.enabled, options };
}

function sanitizeFile(raw: unknown): InstallFeaturesFile | undefined {
	if (raw == null || typeof raw !== "object" || Array.isArray(raw)) return undefined;
	const r = raw as Record<string, unknown>;
	if (r.schemaVersion !== 1) return undefined;
	const features: Record<string, InstalledFeatureState> = {};
	if (r.features != null && typeof r.features === "object" && !Array.isArray(r.features)) {
		for (const [id, state] of Object.entries(r.features as Record<string, unknown>)) {
			const sanitized = sanitizeState(state);
			if (sanitized) features[id] = sanitized;
		}
	}
	const now = new Date().toISOString();
	return {
		schemaVersion: 1,
		installerVersion: typeof r.installerVersion === "string" ? r.installerVersion : VERSION,
		installMethod: "binary",
		installedAt: typeof r.installedAt === "string" ? r.installedAt : now,
		updatedAt: typeof r.updatedAt === "string" ? r.updatedAt : now,
		inferUntil: typeof r.inferUntil === "string" ? r.inferUntil : undefined,
		features,
	};
}

/** True when gateway.json has at least one platform enabled with a file token. */
export function gatewayHasEnabledFileToken(): boolean {
	const cfg = loadGatewayConfig();
	for (const platform of [cfg.telegram, cfg.discord]) {
		if (platform.enabled && typeof platform.token === "string" && platform.token.length > 0) {
			return true;
		}
	}
	return false;
}

function inferPathActive(): boolean {
	// Pre-public 0.80.x is numerically > 0.2.0; still infer so dogfooders work
	// until PR 7 rewrites the version line to 0.1.0.
	if (VERSION.startsWith("0.80.")) return true;
	return !versionGte(VERSION, CHAT_PLATFORMS_INFER_UNTIL);
}

function inferFromGateway(): InstallFeaturesFile | undefined {
	if (!inferPathActive()) return undefined;
	if (!gatewayHasEnabledFileToken()) return undefined;
	const now = new Date().toISOString();
	const file: InstallFeaturesFile = {
		...emptyFile(now),
		inferUntil: CHAT_PLATFORMS_INFER_UNTIL,
		features: {
			"chat-platforms": { enabled: true, options: { autostart: false } },
		},
	};
	saveInstallFeatures(file);
	appendDebugLog("install-features: inferred chat-platforms enabled (file token, autostart false)");
	return file;
}

export function loadInstallFeatures(): InstallFeaturesFile {
	const path = installFeaturesPath();
	if (!existsSync(path)) {
		return inferFromGateway() ?? emptyFile();
	}
	try {
		const parsed = sanitizeFile(JSON.parse(readFileSync(path, "utf-8")));
		return parsed ?? inferFromGateway() ?? emptyFile();
	} catch {
		return inferFromGateway() ?? emptyFile();
	}
}

export function saveInstallFeatures(file: InstallFeaturesFile): void {
	const path = installFeaturesPath();
	const dir = getAgentDir();
	if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
	const tmp = `${path}.tmp-${process.pid}`;
	writeFileSync(tmp, `${JSON.stringify(file, null, 2)}\n`, "utf-8");
	renameSync(tmp, path);
	try {
		chmodSync(path, 0o644);
	} catch {
		// best-effort (Windows ACLs)
	}
}

export function isFeatureEnabled(id: FeatureId): boolean {
	const file = loadInstallFeatures();
	const state = file.features[id];
	if (state) return state.enabled;
	return getFeatureSpec(id)?.defaultEnabled ?? false;
}

export function getFeatureOption(id: FeatureId, option: string): unknown {
	return loadInstallFeatures().features[id]?.options[option];
}

export function coerceBooleanSetValue(raw: string): boolean | undefined {
	if (raw === "true" || raw === "1") return true;
	if (raw === "false" || raw === "0") return false;
	return undefined;
}

export interface ParsedSet {
	id: string;
	option: string;
	value: string;
}

export function parseSetAssignment(raw: string): ParsedSet | undefined {
	const eq = raw.indexOf("=");
	if (eq <= 0) return undefined;
	const lhs = raw.slice(0, eq);
	const value = raw.slice(eq + 1);
	const dot = lhs.indexOf(".");
	if (dot <= 0 || dot === lhs.length - 1) return undefined;
	return { id: lhs.slice(0, dot), option: lhs.slice(dot + 1), value };
}

export type SetupParseResult =
	| {
			ok: true;
			yes: boolean;
			reconfigure: boolean;
			features: string[];
			noFeatures: string[];
			sets: ParsedSet[];
	  }
	| { ok: false; error: string };

/** Parse setup / features-enable flags. Unknown flags are an error. */
export function parseFeatureFlags(argv: string[]): SetupParseResult {
	let yes = false;
	let reconfigure = false;
	const features: string[] = [];
	const noFeatures: string[] = [];
	const sets: ParsedSet[] = [];

	for (let i = 0; i < argv.length; i++) {
		const arg = argv[i];
		if (arg === "--yes" || arg === "-y") {
			yes = true;
			continue;
		}
		if (arg === "--reconfigure") {
			reconfigure = true;
			continue;
		}
		if (arg === "--feature") {
			const id = argv[++i];
			if (!id) return { ok: false, error: "--feature requires an id" };
			features.push(id);
			continue;
		}
		if (arg === "--no-feature") {
			const id = argv[++i];
			if (!id) return { ok: false, error: "--no-feature requires an id" };
			noFeatures.push(id);
			continue;
		}
		if (arg === "--set") {
			const raw = argv[++i];
			if (!raw) return { ok: false, error: "--set requires <id.option>=<value>" };
			const parsed = parseSetAssignment(raw);
			if (!parsed) return { ok: false, error: `invalid --set ${raw}` };
			sets.push(parsed);
			continue;
		}
		if (arg.startsWith("--feature=")) {
			features.push(arg.slice("--feature=".length));
			continue;
		}
		if (arg.startsWith("--no-feature=")) {
			noFeatures.push(arg.slice("--no-feature=".length));
			continue;
		}
		if (arg.startsWith("--set=")) {
			const parsed = parseSetAssignment(arg.slice("--set=".length));
			if (!parsed) return { ok: false, error: `invalid --set ${arg}` };
			sets.push(parsed);
			continue;
		}
		return { ok: false, error: `unknown flag ${arg}` };
	}

	return { ok: true, yes, reconfigure, features, noFeatures, sets };
}

export type ApplyFlagsError = { ok: false; error: string; exitCode: 2 };
export type ApplyFlagsOk = {
	ok: true;
	next: InstallFeaturesFile;
	secrets: Record<string, string>;
	enabledIds: FeatureId[];
	disabledIds: FeatureId[];
};

/**
 * Validate --feature / --no-feature / --set against the catalog and produce
 * the next install-features.json. Secret --set is rejected. --set on a
 * feature that is not being enabled this invocation is rejected.
 */
export function applyFeatureFlags(
	current: InstallFeaturesFile,
	flags: Extract<SetupParseResult, { ok: true }>,
): ApplyFlagsOk | ApplyFlagsError {
	const next: InstallFeaturesFile = {
		...current,
		installerVersion: VERSION,
		updatedAt: new Date().toISOString(),
		features: { ...current.features },
	};
	const secrets: Record<string, string> = {};
	const enabledIds: FeatureId[] = [];
	const disabledIds: FeatureId[] = [];

	for (const id of flags.features) {
		if (!getFeatureSpec(id)) return { ok: false, error: `unknown feature ${id}`, exitCode: 2 };
		const prev = next.features[id];
		next.features[id] = { enabled: true, options: { ...prev?.options } };
		enabledIds.push(id as FeatureId);
	}
	for (const id of flags.noFeatures) {
		if (!getFeatureSpec(id)) return { ok: false, error: `unknown feature ${id}`, exitCode: 2 };
		const prev = next.features[id];
		next.features[id] = { enabled: false, options: { ...prev?.options } };
		disabledIds.push(id as FeatureId);
	}

	for (const set of flags.sets) {
		const spec = getFeatureSpec(set.id);
		if (!spec) return { ok: false, error: `unknown feature ${set.id}`, exitCode: 2 };
		const option = getFeatureOptionSpec(set.id, set.option);
		if (!option) return { ok: false, error: `unknown option ${set.id}.${set.option}`, exitCode: 2 };
		if (option.type === "secret") {
			return {
				ok: false,
				error: `cannot --set a secret option (${set.id}.${set.option}). set LUNR_TELEGRAM_BOT_TOKEN / LUNR_DISCORD_BOT_TOKEN, or run setup in a TTY`,
				exitCode: 2,
			};
		}
		const enablingNow = flags.features.includes(set.id) || next.features[set.id]?.enabled === true;
		if (!enablingNow) {
			return { ok: false, error: `enable the feature first (${set.id})`, exitCode: 2 };
		}
		if (option.type === "boolean") {
			const coerced = coerceBooleanSetValue(set.value);
			if (coerced === undefined) {
				return { ok: false, error: `${set.id}.${set.option} must be true|false|1|0`, exitCode: 2 };
			}
			const prev = next.features[set.id] ?? { enabled: true, options: {} };
			next.features[set.id] = { ...prev, enabled: true, options: { ...prev.options, [set.option]: coerced } };
		}
	}

	return { ok: true, next, secrets, enabledIds, disabledIds };
}

export interface FeatureApplyContext {
	previous: InstalledFeatureState | undefined;
	next: InstalledFeatureState;
	secrets: Record<string, string>;
	nonInteractive: boolean;
}

export interface FeatureHandler {
	apply(ctx: FeatureApplyContext): Promise<void>;
	disable(opts: { purgeSecrets: boolean }): Promise<void>;
}

function persistEnvAndSecretTokens(secrets: Record<string, string>): void {
	const cfg = loadGatewayConfig();
	const telegram = secrets["telegram-token"] || process.env.LUNR_TELEGRAM_BOT_TOKEN || process.env.TELEGRAM_BOT_TOKEN;
	const discord = secrets["discord-token"] || process.env.LUNR_DISCORD_BOT_TOKEN || process.env.DISCORD_BOT_TOKEN;
	if (telegram) {
		cfg.telegram.token = telegram;
		cfg.telegram.enabled = true;
	}
	if (discord) {
		cfg.discord.token = discord;
		cfg.discord.enabled = true;
	}
	saveGatewayConfig(cfg);
}

export const chatPlatformsHandler: FeatureHandler = {
	async apply(ctx) {
		persistEnvAndSecretTokens(ctx.secrets);
		const cfg = loadGatewayConfig();
		if (cfg.telegram.token) cfg.telegram.enabled = true;
		if (cfg.discord.token) cfg.discord.enabled = true;
		saveGatewayConfig(cfg);
		// Autostart OS units land in a follow-up PR. The option is persisted.
		if (ctx.next.options.autostart === true) {
			const hasFileToken = Boolean(cfg.telegram.token || cfg.discord.token);
			if (!hasFileToken) {
				console.error("chat-platforms: autostart requested but no file token in gateway.json — unit not enabled.");
			} else {
				console.error("chat-platforms: autostart recorded; login item install is not in this build yet.");
			}
		}
	},
	async disable(opts) {
		const cfg = loadGatewayConfig();
		cfg.telegram.enabled = false;
		cfg.discord.enabled = false;
		if (opts.purgeSecrets) {
			delete cfg.telegram.token;
			delete cfg.discord.token;
		}
		saveGatewayConfig(cfg);
	},
};

export const FEATURE_HANDLERS: Record<FeatureId, FeatureHandler> = {
	"chat-platforms": chatPlatformsHandler,
};

export function appendInstallLog(line: string): void {
	try {
		const dir = getAgentDir();
		if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
		const path = join(dir, "install.log");
		writeFileSync(path, `${new Date().toISOString()} ${line}\n`, { encoding: "utf-8", flag: "a" });
	} catch {
		// best-effort
	}
}

export const PRODUCT_UNINSTALL_FLAGS = new Set(["--purge", "--yes", "-y"]);

/** Product uninstall only when every remaining argv is empty or a product flag. */
export function isProductUninstallArgv(rest: string[]): boolean {
	return rest.every((arg) => PRODUCT_UNINSTALL_FLAGS.has(arg));
}

export function deliverMentionsChatPlatform(deliver: string): boolean {
	return deliver.split(",").some((part) => {
		const name = part.trim().split(":")[0]?.toLowerCase();
		return name === "telegram" || name === "discord";
	});
}

export function chatPlatformDeliverBlockedMessage(): string {
	return "chat platforms are not enabled. Enable with: lunr features enable chat-platforms";
}

